          "yomi": "つゆしもに しおたれて、ところ さだめず まどいあるき、おやの いさめ、よの そしりを つつむに、こころの いとまなく、あうさ かるさに おもいみだれ、さるは ひとりねがちに、まどろむ よるなきこそ、おかしけれ。",
