          "text": "名刀を所持する人、金銀の飾り鞘に収むるより、質素なる黒漆や白木の鞘に入れたるこそ、研ぎ澄まされし刃の冴え引き立ちて見事なれ。",
          "yomi": "めいとうを しょじする ひと、きんぎんの かざりざやに おさむるより、しっそなる くろうるしや しらきの さやに いれたるこそ、とぎすまされし やいばの さえ ひきたちて みごとなれ。",
