          "yomi": "だいじんの だいきょうは、さるべき ところを もうしうけて おこなう、つねの ことなり。うじの さだいじんどのは、ひがしさんじょうどのにおいて おこなわる。ふるき かくしきを まもりて もよおすこそ、くじの おもき ところなれ。",
